<?php
declare(strict_types=1);

function finance_pro_guard(): void {
    if(!can_treasury()){http_response_code(403);exit('Acesso restrito à Tesouraria.');}
}
function finance_status_label(string $status): string {
    return ['open'=>'Em aberto','paid'=>'Pago','cancelled'=>'Cancelado','pending'=>'Pendente','posted'=>'Lançado','skipped'=>'Ignorado','matched'=>'Conciliado','ignored'=>'Ignorado','closed'=>'Fechado','reopened'=>'Reaberto','requested'=>'Solicitado','approved'=>'Aprovado','purchased'=>'Comprado'][$status]??$status;
}
function finance_month_label(string $month): string {
    [$f]=finance_month_bounds($month);$months=[1=>'janeiro',2=>'fevereiro',3=>'março',4=>'abril',5=>'maio',6=>'junho',7=>'julho',8=>'agosto',9=>'setembro',10=>'outubro',11=>'novembro',12=>'dezembro'];
    return $months[(int)substr($f,5,2)].' de '.substr($f,0,4);
}
function finance_prefill_from_sources(int $cid): array {
    $p=['direction'=>'expense','income_kind'=>'other','amount'=>'','date'=>date('Y-m-d'),'description'=>'','category_id'=>0,'account_id'=>0,'fund_id'=>0,'cost_center_id'=>0,'supplier'=>'','payment_method'=>'','document_number'=>'','member_id'=>0,'occurrence_id'=>0,'bank_line_id'=>0];
    $occ=(int)($_GET['occurrence']??0);
    if($occ){
        $r=one("SELECT o.id occurrence_id,o.due_date,r.* FROM recurring_occurrences o JOIN recurring_financial_items r ON r.id=o.recurring_id WHERE o.id=? AND o.church_id=? AND o.status='pending'",[$occ,$cid]);
        if($r)$p=array_merge($p,['direction'=>$r['direction'],'income_kind'=>$r['income_kind']?:'other','amount'=>(string)$r['amount'],'date'=>$r['due_date'],'description'=>$r['description'],'category_id'=>(int)$r['category_id'],'account_id'=>(int)$r['account_id'],'fund_id'=>(int)$r['fund_id'],'cost_center_id'=>(int)$r['cost_center_id'],'supplier'=>(string)($r['supplier']??''),'occurrence_id'=>(int)$r['occurrence_id']]);
    }
    $bank=(int)($_GET['bank_line']??0);
    if($bank){
        $r=one("SELECT * FROM bank_statement_lines WHERE id=? AND church_id=? AND status='pending'",[$bank,$cid]);
        if($r)$p=array_merge($p,['direction'=>(float)$r['amount']>=0?'income':'expense','amount'=>(string)abs((float)$r['amount']),'date'=>$r['transaction_date'],'description'=>$r['description'],'account_id'=>(int)$r['account_id'],'bank_line_id'=>(int)$r['id']]);
    }
    $kind=(string)($_GET['kind']??'');
    if(in_array($kind,['tithe','offering','donation','expense','income'],true)){
        if($kind==='expense')$p['direction']='expense';
        elseif($kind==='income')$p['direction']='income';
        else{$p['direction']='income';$p['income_kind']=$kind;}
    }
    return $p;
}

function finance_route_treasury(int $cid): never {
    finance_pro_guard();finance_seed_defaults($cid);finance_ensure_occurrences($cid);
    [$from,$to,$month]=finance_month_bounds(date('Y-m'));
    $tot=finance_period_totals($cid,$from,$to);$p=finance_pending_summary($cid,$month);
    $recent=all("SELECT t.*,a.name account_name FROM transactions t LEFT JOIN accounts a ON a.id=t.account_id WHERE t.church_id=? ORDER BY t.transaction_date DESC,t.id DESC LIMIT 8",[$cid]);
    $needs=(int)(one("SELECT COUNT(*) c FROM church_needs WHERE church_id=? AND status IN ('requested','approved')",[$cid])['c']??0);
    page_top('Tesouraria','Painel de conferência · o que entrou, saiu e ainda falta fazer');flash();
    echo '<div class="treasury-hero"><div><span class="eyebrow-app">TESOURARIA PROFISSIONAL</span><h2>'.e(finance_month_label($month)).'</h2><p>Use este painel como checklist diário. Quando uma pendência aparecer aqui, ela ainda precisa de atenção.</p></div><a class="btn" href="/?r=finance">+ Novo lançamento</a></div>';
    echo '<div class="grid treasury-kpis"><div class="card metric"><small>Entradas do mês</small><strong class="money in">'.e(money_br((float)$tot['income'])).'</strong></div><div class="card metric"><small>Saídas do mês</small><strong class="money out">'.e(money_br((float)$tot['expense'])).'</strong></div><div class="card metric"><small>Saldo do mês</small><strong>'.e(money_br((float)$tot['income']-(float)$tot['expense'])).'</strong></div><div class="card metric"><small>Situação do mês</small><strong class="'.($p['closed']?'money in':'').'">'.($p['closed']?'Fechado':'Em conferência').'</strong></div></div>';

    $tasks=[
      ['Comprovantes faltando',(int)$p['missing_receipts'],'finance','Anexe o recibo das despesas para não esquecer depois.'],
      ['Extrato sem conciliar',(int)$p['bank_pending'],'reconciliation','Movimentações do banco ainda sem ligação com o sistema.'],
      ['Lançamentos recorrentes',(int)$p['recurring_pending'],'recurring','Contas mensais previstas que ainda não foram lançadas.'],
      ['Contas vencidas',(int)$p['overdue_payables'],'payables','Contas a pagar que chegaram ao vencimento e continuam abertas.'],
      ['Necessidades da igreja',$needs,'needs','Compras, reparos ou itens solicitados e ainda em acompanhamento.'],
    ];
    echo '<div class="dashboard-section"><div class="dashboard-section-head"><div><h3>O que falta fazer</h3><p>O objetivo é chegar ao fechamento do mês sem nenhuma pendência.</p></div></div><div class="treasury-tasks">';
    foreach($tasks as $t){$ok=$t[1]===0;echo '<a class="task-card '.($ok?'task-ok':'task-attention').'" href="/?r='.e($t[2]).'"><span class="task-count">'.(int)$t[1].'</span><span><b>'.e($t[0]).'</b><small>'.e($ok?'Tudo certo.':$t[3]).'</small></span><i>›</i></a>';}
    echo '</div></div>';

    echo '<div class="dashboard-section"><div class="dashboard-section-head"><div><h3>Ações rápidas</h3><p>Fluxos feitos para o tesoureiro não precisar procurar telas.</p></div></div><div class="quick-actions treasury-actions">';
    $quick=[['finance&kind=tithe','DÍZ','Lançar dízimo','Escolher membro e valor'],['finance&kind=offering','OF','Lançar oferta','Entrada do culto/campanha'],['finance&kind=expense','SAÍ','Registrar despesa','Pagamento com comprovante'],['payables','PAG','Conta a pagar','Cadastrar vencimento'],['reconciliation','BAN','Conciliar banco','Importar OFX ou CSV'],['closing','✓','Fechar mês','Checklist e conferência'],['budgets','ORÇ','Orçamento','Previsto x realizado'],['reports','PDF','Prestação de contas','Visualizar, imprimir e PDF']];
    foreach($quick as $q)echo '<a class="quick-action" href="/?r='.$q[0].'"><span class="quick-action-icon">'.$q[1].'</span><span><b>'.$q[2].'</b><small>'.$q[3].'</small></span></a>';
    echo '</div></div>';

    echo '<div class="dashboard-section"><div class="card"><div class="card-title-row"><div><h3>Últimas movimentações</h3><p class="muted">Confira se o que aconteceu no caixa/banco já está registrado.</p></div><a class="btn light" href="/?r=finance">Ver lançamentos</a></div><div class="table-wrap"><table class="table"><thead><tr><th>DATA</th><th>TIPO</th><th>DESCRIÇÃO</th><th>CONTA</th><th>VALOR</th></tr></thead><tbody>';
    if(!$recent)echo '<tr><td colspan="5">Nenhuma movimentação cadastrada.</td></tr>';
    foreach($recent as $r){$in=$r['direction']==='income';echo '<tr><td>'.e(br_date((string)$r['transaction_date'])).'</td><td>'.($in?'Entrada':'Saída').'</td><td>'.e($r['description']).'</td><td>'.e($r['account_name']??'—').'</td><td class="money '.($in?'in':'out').'">'.($in?'+ ':'- ').e(money_br((float)$r['amount'])).'</td></tr>';}
    echo '</tbody></table></div></div></div>';page_bottom();exit;
}

function finance_route_finance(int $cid): never {
    finance_pro_guard();finance_seed_defaults($cid);
    if($_SERVER['REQUEST_METHOD']==='POST'){
        verify_csrf();$action=(string)($_POST['action']??'create');
        try{
            if($action==='attach_receipt'){
                $id=(int)($_POST['transaction_id']??0);$tx=one("SELECT * FROM transactions WHERE id=? AND church_id=? AND status='posted'",[$id,$cid]);if(!$tx)throw new RuntimeException('Lançamento não encontrado.');
                if(empty($_FILES['receipt']))throw new RuntimeException('Selecione um comprovante.');
                $receipt=save_receipt_upload($cid,$_FILES['receipt']);
                q('UPDATE transactions SET receipt_path=?,receipt_name=?,receipt_mime=?,receipt_size=? WHERE id=? AND church_id=?',[$receipt['path'],$receipt['name'],$receipt['mime'],$receipt['size'],$id,$cid]);
                audit('attach_transaction_receipt','transaction',$id);set_flash('Comprovante anexado.');
            }elseif($action==='reverse'){
                $id=(int)($_POST['transaction_id']??0);$reason=trim((string)($_POST['reason']??''));$tx=one("SELECT * FROM transactions WHERE id=? AND church_id=? AND status='posted'",[$id,$cid]);
                if(!$tx)throw new RuntimeException('Lançamento não encontrado.');finance_assert_open_period($cid,(string)$tx['transaction_date']);
                if(strlen($reason)<5)throw new RuntimeException('Informe o motivo do estorno.');
                q("UPDATE transactions SET status='cancelled',reversed_at=NOW(),reversed_by=?,reversal_reason=? WHERE id=? AND church_id=?",[(int)user()['id'],$reason,$id,$cid]);
                if(!empty($tx['bank_line_id']))q("UPDATE bank_statement_lines SET status='pending',matched_transaction_id=NULL,resolved_at=NULL WHERE id=? AND church_id=?",[(int)$tx['bank_line_id'],$cid]);
                audit('reverse_transaction','transaction',$id,['reason'=>$reason]);set_flash('Lançamento estornado sem apagar o histórico.');
            }else{
                $dir=in_array((string)($_POST['direction']??''),['income','expense'],true)?(string)$_POST['direction']:'expense';
                $kind=$dir==='income'?(string)($_POST['income_kind']??'other'):null;if($dir==='income'&&!in_array($kind,['tithe','offering','donation','other'],true))$kind='other';
                $date=(string)($_POST['transaction_date']??date('Y-m-d'));finance_assert_open_period($cid,$date);
                $amount=(float)($_POST['amount']??0);if($amount<=0)throw new RuntimeException('Informe um valor maior que zero.');
                $cat=finance_category($cid,(int)($_POST['category_id']??0));if(!$cat)throw new RuntimeException('Escolha a categoria.');
                if($cat['direction']!=='both'&&$cat['direction']!==$dir)throw new RuntimeException('A categoria escolhida não corresponde ao tipo de lançamento.');
                $memberId=null;if($dir==='income'&&$kind==='tithe'){$candidate=(int)($_POST['member_id']??0);$m=one("SELECT id FROM members WHERE id=? AND church_id=? AND status='active'",[$candidate,$cid]);if(!$m)throw new RuntimeException('Escolha o membro do dízimo.');$memberId=$candidate;}
                $receipt=null;if(!empty($_FILES['receipt']['name']))$receipt=save_receipt_upload($cid,$_FILES['receipt']);
                $occ=(int)($_POST['occurrence_id']??0);$bank=(int)($_POST['bank_line_id']??0);
                q("INSERT INTO transactions(church_id,account_id,member_id,direction,income_kind,category_id,category,fund_id,cost_center_id,description,supplier,payment_method,document_number,amount,transaction_date,created_by,receipt_path,receipt_name,receipt_mime,receipt_size,recurring_occurrence_id,bank_line_id)
                   VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",[
                   $cid,(int)($_POST['account_id']??0)?:null,$memberId,$dir,$kind,(int)$cat['id'],$cat['name'],(int)($_POST['fund_id']??0)?:null,(int)($_POST['cost_center_id']??0)?:null,
                   trim((string)($_POST['description']??'')),trim((string)($_POST['supplier']??''))?:null,trim((string)($_POST['payment_method']??''))?:null,trim((string)($_POST['document_number']??''))?:null,
                   $amount,$date,(int)user()['id'],$receipt['path']??null,$receipt['name']??null,$receipt['mime']??null,$receipt['size']??null,$occ?:null,$bank?:null
                ]);
                $id=(int)db()->lastInsertId();
                if($occ)q("UPDATE recurring_occurrences SET status='posted',transaction_id=?,resolved_by=?,resolved_at=NOW() WHERE id=? AND church_id=?",[$id,(int)user()['id'],$occ,$cid]);
                if($bank)q("UPDATE bank_statement_lines SET status='matched',matched_transaction_id=?,resolved_at=NOW() WHERE id=? AND church_id=?",[$id,$bank,$cid]);
                audit('create_transaction','transaction',$id,['direction'=>$dir,'category'=>$cat['name'],'member_id'=>$memberId,'receipt'=>(bool)$receipt]);
                set_flash('Lançamento registrado'.($dir==='expense'&&!$receipt?' — lembrete: o comprovante ainda está pendente.':'.'));
            }
        }catch(Throwable $e){error_log('finance-pro: '.$e->getMessage());set_flash($e->getMessage(),'error');}
        redirect('/?r=finance');
    }

    $p=finance_prefill_from_sources($cid);$accounts=finance_accounts($cid);$cats=finance_categories($cid);$funds=finance_funds($cid);$centers=finance_cost_centers($cid);$members=all("SELECT id,name FROM members WHERE church_id=? AND status='active' ORDER BY name",[$cid]);
    $rows=all("SELECT t.*,a.name account_name,m.name member_name,f.name fund_name,cc.name cost_center_name FROM transactions t LEFT JOIN accounts a ON a.id=t.account_id LEFT JOIN members m ON m.id=t.member_id LEFT JOIN finance_funds f ON f.id=t.fund_id LEFT JOIN cost_centers cc ON cc.id=t.cost_center_id WHERE t.church_id=? ORDER BY t.transaction_date DESC,t.id DESC LIMIT 250",[$cid]);
    page_top('Lançamentos','Tesouraria · registro simples com classificação, comprovante e rastreabilidade');flash();
    echo '<div class="finance-choice"><a href="/?r=finance&kind=tithe"><b>Dízimo</b><small>Vinculado ao membro</small></a><a href="/?r=finance&kind=offering"><b>Oferta</b><small>Entrada coletiva</small></a><a href="/?r=finance&kind=donation"><b>Doação</b><small>Outra contribuição</small></a><a href="/?r=finance&kind=expense"><b>Despesa</b><small>Pagamento / compra</small></a><a href="/?r=finance&kind=income"><b>Outra entrada</b><small>Receita diversa</small></a></div>';
    echo '<div class="card"><div class="card-title-row"><div><h3>Novo lançamento</h3><p class="muted">Preencha o que aconteceu. O sistema organiza a classificação para relatórios e transparência.</p></div><a class="btn light" href="/?r=treasury">Voltar ao painel</a></div><form method="post" enctype="multipart/form-data" id="financeProForm">'.csrf_input().'<input type="hidden" name="action" value="create"><input type="hidden" name="occurrence_id" value="'.(int)$p['occurrence_id'].'"><input type="hidden" name="bank_line_id" value="'.(int)$p['bank_line_id'].'"><div class="form-grid">';
    echo '<div><label>Movimentação</label><select name="direction" id="fpDirection"><option value="income" '.($p['direction']==='income'?'selected':'').'>Entrada</option><option value="expense" '.($p['direction']==='expense'?'selected':'').'>Saída / despesa</option></select></div><div id="fpKindBox"><label>Tipo da entrada</label><select name="income_kind" id="fpKind"><option value="other" '.($p['income_kind']==='other'?'selected':'').'>Outra entrada</option><option value="tithe" '.($p['income_kind']==='tithe'?'selected':'').'>Dízimo</option><option value="offering" '.($p['income_kind']==='offering'?'selected':'').'>Oferta</option><option value="donation" '.($p['income_kind']==='donation'?'selected':'').'>Doação</option></select></div>';
    echo '<div id="fpMemberBox"><label>Membro do dízimo</label><select name="member_id"><option value="">Selecione...</option>';foreach($members as $m)echo '<option value="'.(int)$m['id'].'">'.e($m['name']).'</option>';echo '</select></div>';
    echo '<div><label>Categoria</label><select name="category_id" id="fpCategory" required><option value="">Selecione...</option>';foreach($cats as $c)echo '<option data-direction="'.e($c['direction']).'" value="'.(int)$c['id'].'" '.((int)$p['category_id']===(int)$c['id']?'selected':'').'>'.e(($c['accounting_code']?$c['accounting_code'].' · ':'').$c['name']).'</option>';echo '</select></div>';
    echo '<div><label>Valor</label><input name="amount" type="number" min="0.01" step="0.01" value="'.e($p['amount']).'" required></div><div><label>Data</label><input name="transaction_date" type="date" value="'.e($p['date']).'" required></div>';
    echo '<div><label>Conta / caixa</label><select name="account_id"><option value="">Não informado</option>';foreach($accounts as $a)echo '<option value="'.(int)$a['id'].'" '.((int)$p['account_id']===(int)$a['id']?'selected':'').'>'.e($a['name']).'</option>';echo '</select></div>';
    echo '<div><label>Fundo / destinação</label><select name="fund_id"><option value="">Fundo Geral / não informado</option>';foreach($funds as $f)echo '<option value="'.(int)$f['id'].'" '.((int)$p['fund_id']===(int)$f['id']?'selected':'').'>'.e($f['name']).($f['restricted']?' · restrito':'').'</option>';echo '</select></div>';
    echo '<div><label>Centro de custo</label><select name="cost_center_id"><option value="">Não informado</option>';foreach($centers as $c)echo '<option value="'.(int)$c['id'].'" '.((int)$p['cost_center_id']===(int)$c['id']?'selected':'').'>'.e($c['name']).'</option>';echo '</select></div>';
    echo '<div id="fpSupplier"><label>Fornecedor / favorecido</label><input name="supplier" value="'.e($p['supplier']).'" placeholder="Quem recebeu o pagamento"></div><div><label>Forma de pagamento</label><select name="payment_method"><option value="">Não informado</option><option>Dinheiro</option><option>PIX</option><option>Transferência</option><option>Cartão</option><option>Boleto</option><option>Débito automático</option><option>Cheque</option></select></div><div><label>Nº documento / NF / recibo</label><input name="document_number" value="'.e($p['document_number']).'"></div>';
    echo '<div class="full"><label>Descrição / histórico</label><input name="description" value="'.e($p['description']).'" required placeholder="Ex.: pagamento da energia do templo"></div><div class="full"><label>Comprovante <span class="optional">(recomendado para despesas)</span></label><input type="file" name="receipt" accept="application/pdf,image/jpeg,image/png,image/webp"><small class="hint">Pode anexar agora ou depois. O painel da Tesouraria avisa quando uma despesa está sem comprovante.</small></div></div><p><button class="btn">Salvar lançamento</button></p></form></div>';
    echo '<script>(function(){const d=document.getElementById("fpDirection"),k=document.getElementById("fpKind"),kb=document.getElementById("fpKindBox"),mb=document.getElementById("fpMemberBox"),sup=document.getElementById("fpSupplier"),cat=document.getElementById("fpCategory");function sync(){const inc=d.value==="income";kb.hidden=!inc;mb.hidden=!(inc&&k.value==="tithe");sup.hidden=inc;Array.from(cat.options).forEach(o=>{if(!o.value)return;o.hidden=!(o.dataset.direction==="both"||o.dataset.direction===d.value)});if(cat.selectedOptions[0]&&cat.selectedOptions[0].hidden)cat.value="";}d.addEventListener("change",sync);k.addEventListener("change",sync);sync()})();</script>';

    echo '<br><div class="card"><div class="card-title-row"><div><h3>Histórico financeiro</h3><p class="muted">Nada é apagado: estornos permanecem registrados para auditoria.</p></div></div><div class="table-wrap"><table class="table"><thead><tr><th>DATA</th><th>TIPO</th><th>CATEGORIA</th><th>HISTÓRICO</th><th>FUNDO</th><th>COMPROVANTE</th><th>VALOR</th><th>AÇÃO</th></tr></thead><tbody>';
    foreach($rows as $r){$in=$r['direction']==='income';$cancel=$r['status']==='cancelled';echo '<tr class="'.($cancel?'row-cancelled':'').'"><td>'.e(br_date((string)$r['transaction_date'])).'</td><td>'.($in?'Entrada':'Saída').($cancel?' · ESTORNADO':'').'</td><td>'.e($r['category']).'</td><td>'.e($r['description']).'</td><td>'.e($r['fund_name']??'—').'</td><td>';if($r['receipt_path'])echo '<a class="receipt-link" target="_blank" href="/?r=receipt&id='.(int)$r['id'].'">Ver comprovante</a>';elseif(!$cancel&& !$in)echo '<form class="inline-upload" method="post" enctype="multipart/form-data">'.csrf_input().'<input type="hidden" name="action" value="attach_receipt"><input type="hidden" name="transaction_id" value="'.(int)$r['id'].'"><input type="file" name="receipt" accept="application/pdf,image/jpeg,image/png,image/webp" required><button class="btn light">Anexar</button></form>';else echo '—';echo '</td><td class="money '.($in?'in':'out').'">'.($in?'+ ':'- ').e(money_br((float)$r['amount'])).'</td><td>';if(!$cancel)echo '<details class="reverse-box"><summary>Estornar</summary><form method="post">'.csrf_input().'<input type="hidden" name="action" value="reverse"><input type="hidden" name="transaction_id" value="'.(int)$r['id'].'"><input name="reason" placeholder="Motivo do estorno" required><button class="btn danger">Confirmar</button></form></details>';else echo '<span class="pill">Histórico preservado</span>';echo '</td></tr>';}
    echo '</tbody></table></div></div>';page_bottom();exit;
}

function finance_route_payables(int $cid): never {
    finance_pro_guard();finance_seed_defaults($cid);
    if($_SERVER['REQUEST_METHOD']==='POST'){
        verify_csrf();$action=(string)($_POST['action']??'create');
        try{
            if($action==='create'){
                $amount=(float)($_POST['amount']??0);if($amount<=0)throw new RuntimeException('Informe o valor.');
                q("INSERT INTO payables(church_id,supplier,description,category,amount,due_date,account_id,fund_id,cost_center_id,status) VALUES(?,?,?,?,?,?,?,?,?,'open')",[$cid,trim((string)$_POST['supplier']),trim((string)$_POST['description']),trim((string)($_POST['category']??'')),$amount,$_POST['due_date'],(int)($_POST['account_id']??0)?:null,(int)($_POST['fund_id']??0)?:null,(int)($_POST['cost_center_id']??0)?:null]);audit('create_payable','payable',(int)db()->lastInsertId());set_flash('Conta a pagar cadastrada. Ela aparecerá nas pendências até ser paga.');
            }elseif($action==='pay'){
                $id=(int)($_POST['payable_id']??0);$p=one("SELECT * FROM payables WHERE id=? AND church_id=? AND status='open'",[$id,$cid]);if(!$p)throw new RuntimeException('Conta não encontrada ou já resolvida.');
                $date=(string)($_POST['paid_at']??date('Y-m-d'));finance_assert_open_period($cid,$date);
                $cat=one("SELECT * FROM finance_categories WHERE church_id=? AND direction='expense' AND name=? LIMIT 1",[$cid,(string)$p['category']]);if(!$cat)$cat=one("SELECT * FROM finance_categories WHERE church_id=? AND direction='expense' ORDER BY id LIMIT 1",[$cid]);
                $receipt=null;if(!empty($_FILES['receipt']['name']))$receipt=save_receipt_upload($cid,$_FILES['receipt']);
                q("INSERT INTO transactions(church_id,account_id,direction,category_id,category,fund_id,cost_center_id,description,supplier,payment_method,amount,transaction_date,created_by,receipt_path,receipt_name,receipt_mime,receipt_size) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",[$cid,(int)($_POST['account_id']??$p['account_id'])?:null,'expense',(int)($cat['id']??0)?:null,(string)($p['category']?:($cat['name']??'Despesa')),(int)$p['fund_id']?:null,(int)$p['cost_center_id']?:null,(string)$p['description'],(string)$p['supplier'],trim((string)($_POST['payment_method']??''))?:null,(float)$p['amount'],$date,(int)user()['id'],$receipt['path']??null,$receipt['name']??null,$receipt['mime']??null,$receipt['size']??null]);
                $tx=(int)db()->lastInsertId();q("UPDATE payables SET status='paid',paid_at=?,paid_transaction_id=? WHERE id=? AND church_id=?",[$date,$tx,$id,$cid]);audit('pay_payable','payable',$id,['transaction_id'=>$tx]);set_flash('Pagamento registrado e vinculado ao financeiro.');
            }elseif($action==='cancel'){
