    echo '<div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>VENCIMENTO</th><th>FORNECEDOR</th><th>DESCRIÇÃO</th><th>VALOR</th><th>STATUS</th><th>AÇÃO</th></tr></thead><tbody>';
    foreach($rows as $r){
