        if($r['status']==='open'){
            echo '<details class="pay-box"><summary class="btn green">Registrar pagamento</summary><form method="post" enctype="multipart/form-data">'.csrf_input().'<input type="hidden" name="action" value="pay"><input type="hidden" name="payable_id" value="'.(int)$r['id'].'"><label>Data do pagamento</label><input type="date" name="paid_at" value="'.date('Y-m-d').'" required><label>Conta</label><select name="account_id"><option value="">Selecione...</option>';
            foreach($accounts as $a)echo '<option value="'.(int)$a['id'].'">'.e($a['name']).'</option>';
            echo '</select><label>Forma</label><select name="payment_method"><option>PIX</option><option>Dinheiro</option><option>Transferência</option><option>Boleto</option><option>Débito automático</option><option>Cartão</option></select><label>Comprovante</label><input type="file" name="receipt" accept="application/pdf,image/jpeg,image/png,image/webp"><button class="btn">Pagar e lançar</button></form></details>';
