                $dir=in_array((string)($_POST['direction']??''),['income','expense'],true)?(string)$_POST['direction']:'expense';$cat=finance_category($cid,(int)($_POST['category_id']??0));if(!$cat)throw new RuntimeException('Escolha a categoria.');
                q("INSERT INTO recurring_financial_items(church_id,direction,income_kind,category_id,category,description,supplier,amount,due_day,account_id,fund_id,cost_center_id,receipt_required,active,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,1,?)",[$cid,$dir,$dir==='income'?(string)($_POST['income_kind']??'other'):null,(int)$cat['id'],$cat['name'],trim((string)$_POST['description']),trim((string)($_POST['supplier']??''))?:null,(float)$_POST['amount'],max(1,min(31,(int)$_POST['due_day'])),(int)($_POST['account_id']??0)?:null,(int)($_POST['fund_id']??0)?:null,(int)($_POST['cost_center_id']??0)?:null,!empty($_POST['receipt_required'])?1:0,(int)user()['id']]);audit('create_recurring','recurring',(int)db()->lastInsertId());set_flash('Rotina mensal criada.');
            }elseif($action==='toggle'){$id=(int)$_POST['id'];q('UPDATE recurring_financial_items SET active=IF(active=1,0,1) WHERE id=? AND church_id=?',[$id,$cid]);audit('toggle_recurring','recurring',$id);set_flash('Rotina atualizada.');
            }elseif($action==='skip'){$id=(int)$_POST['occurrence_id'];q("UPDATE recurring_occurrences SET status='skipped',resolved_by=?,resolved_at=NOW(),note=? WHERE id=? AND church_id=? AND status='pending'",[(int)user()['id'],trim((string)($_POST['note']??'Ignorado neste mês')),$id,$cid]);audit('skip_recurring_occurrence','recurring_occurrence',$id);set_flash('Pendência marcada como não aplicável neste mês.');}
        }catch(Throwable $e){set_flash($e->getMessage(),'error');}
        redirect('/?r=recurring');
    }
    finance_ensure_occurrences($cid);$items=all('SELECT * FROM recurring_financial_items WHERE church_id=? ORDER BY active DESC,due_day,description',[$cid]);$occ=all("SELECT o.*,r.description,r.amount,r.direction,r.supplier FROM recurring_occurrences o JOIN recurring_financial_items r ON r.id=o.recurring_id WHERE o.church_id=? AND o.period_month=? ORDER BY o.due_date",[$cid,date('Y-m')]);$cats=finance_categories($cid);$accounts=finance_accounts($cid);$funds=finance_funds($cid);$centers=finance_cost_centers($cid);
    page_top('Lançamentos recorrentes','Cadastre uma vez e o sistema lembra todos os meses');flash();
    echo '<div class="card"><h3>Nova rotina mensal</h3><form method="post">'.csrf_input().'<input type="hidden" name="action" value="create"><div class="form-grid"><div><label>Tipo</label><select name="direction"><option value="expense">Despesa</option><option value="income">Entrada</option></select></div><div><label>Categoria</label><select name="category_id" required>';foreach($cats as $c)echo '<option value="'.(int)$c['id'].'">'.e($c['name']).' · '.e($c['direction']).'</option>';echo '</select></div><div><label>Descrição</label><input name="description" required placeholder="Ex.: Energia elétrica"></div><div><label>Fornecedor</label><input name="supplier"></div><div><label>Valor previsto</label><input type="number" step="0.01" min="0" name="amount" value="0"></div><div><label>Dia de vencimento / lembrete</label><input type="number" min="1" max="31" name="due_day" value="10" required></div><div><label>Conta</label><select name="account_id"><option value="">Não definida</option>';foreach($accounts as $a)echo '<option value="'.(int)$a['id'].'">'.e($a['name']).'</option>';echo '</select></div><div><label>Fundo</label><select name="fund_id"><option value="">Não definido</option>';foreach($funds as $f)echo '<option value="'.(int)$f['id'].'">'.e($f['name']).'</option>';echo '</select></div><div><label>Centro de custo</label><select name="cost_center_id"><option value="">Não definido</option>';foreach($centers as $c)echo '<option value="'.(int)$c['id'].'">'.e($c['name']).'</option>';echo '</select></div><div><label><input type="checkbox" name="receipt_required" value="1"> Exigir comprovante</label></div></div><p><button class="btn">Criar lembrete mensal</button></p></form></div><br>';
    echo '<div class="card"><h3>Pendências de '.e(finance_month_label(date('Y-m'))).'</h3><div class="recurring-list">';if(!$occ)echo '<div class="dashboard-empty">Nenhuma rotina mensal cadastrada.</div>';foreach($occ as $o){echo '<div class="recurring-row"><div><b>'.e($o['description']).'</b><small>Vence '.e(br_date($o['due_date'])).' · '.e(money_br((float)$o['amount'])).'</small></div><span class="pill">'.e(finance_status_label($o['status'])).'</span>';if($o['status']==='pending')echo '<div class="action-row"><a class="btn" href="/?r=finance&occurrence='.(int)$o['id'].'">Lançar agora</a><form method="post">'.csrf_input().'<input type="hidden" name="action" value="skip"><input type="hidden" name="occurrence_id" value="'.(int)$o['id'].'"><button class="btn light">Não se aplica</button></form></div>';echo '</div>';}echo '</div></div><br>';
    echo '<div class="card"><h3>Rotinas cadastradas</h3><div class="table-wrap"><table class="table"><thead><tr><th>DIA</th><th>DESCRIÇÃO</th><th>TIPO</th><th>VALOR PREV.</th><th>ATIVA</th><th></th></tr></thead><tbody>';foreach($items as $i)echo '<tr><td>'.(int)$i['due_day'].'</td><td>'.e($i['description']).'</td><td>'.($i['direction']==='income'?'Entrada':'Despesa').'</td><td>'.e(money_br((float)$i['amount'])).'</td><td>'.($i['active']?'Sim':'Não').'</td><td><form method="post">'.csrf_input().'<input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="'.(int)$i['id'].'"><button class="btn light">'.($i['active']?'Desativar':'Ativar').'</button></form></td></tr>';echo '</tbody></table></div></div>';page_bottom();exit;
}

function finance_route_reconciliation(int $cid): never {
    finance_pro_guard();
    if($_SERVER['REQUEST_METHOD']==='POST'){
        verify_csrf();$action=(string)($_POST['action']??'upload');
        try{
            if($action==='upload'){
                if(empty($_FILES['statement']['tmp_name']))throw new RuntimeException('Selecione o arquivo OFX ou CSV.');
                $name=(string)$_FILES['statement']['name'];$ext=strtolower(pathinfo($name,PATHINFO_EXTENSION));if(!in_array($ext,['ofx','csv'],true))throw new RuntimeException('Use arquivo OFX ou CSV.');
                $lines=finance_parse_statement((string)$_FILES['statement']['tmp_name'],$name);if(!$lines)throw new RuntimeException('Nenhuma movimentação reconhecida no arquivo.');
                $batch=bin2hex(random_bytes(8));$added=0;$account=(int)($_POST['account_id']??0)?:null;
                foreach($lines as $l){$key=hash('sha256',$cid.'|'.$l['key']);try{q("INSERT IGNORE INTO bank_statement_lines(church_id,account_id,import_batch,external_key,transaction_date,description,amount,status,imported_by) VALUES(?,?,?,?,?,?,?,'pending',?)",[$cid,$account,$batch,$key,$l['date'],$l['description'],$l['amount'],(int)user()['id']]);if(db()->lastInsertId())$added++;}catch(Throwable $e){}}
                audit('import_bank_statement','bank_statement',null,['file'=>$name,'rows'=>$added]);set_flash($added.' movimentação(ões) nova(s) importada(s).');
            }elseif($action==='auto_match'){
                $lines=all("SELECT * FROM bank_statement_lines WHERE church_id=? AND status='pending' ORDER BY transaction_date",[$cid]);$matched=0;
                foreach($lines as $l){$dir=(float)$l['amount']>=0?'income':'expense';$amt=abs((float)$l['amount']);$tx=one("SELECT id FROM transactions WHERE church_id=? AND status='posted' AND direction=? AND ABS(amount-?)<0.01 AND transaction_date BETWEEN DATE_SUB(?,INTERVAL 2 DAY) AND DATE_ADD(?,INTERVAL 2 DAY) AND bank_line_id IS NULL ORDER BY ABS(DATEDIFF(transaction_date,?)),id LIMIT 1",[$cid,$dir,$amt,$l['transaction_date'],$l['transaction_date'],$l['transaction_date']]);if($tx){q("UPDATE bank_statement_lines SET status='matched',matched_transaction_id=?,resolved_at=NOW() WHERE id=? AND church_id=?",[(int)$tx['id'],(int)$l['id'],$cid]);q("UPDATE transactions SET bank_line_id=? WHERE id=? AND church_id=?",[(int)$l['id'],(int)$tx['id'],$cid]);$matched++;}}
                audit('auto_reconcile_bank','bank_statement',null,['matched'=>$matched]);set_flash($matched.' movimentação(ões) conciliada(s) automaticamente.');
            }elseif($action==='match'){
                $lineId=(int)$_POST['line_id'];$txId=(int)$_POST['transaction_id'];$l=one("SELECT * FROM bank_statement_lines WHERE id=? AND church_id=? AND status='pending'",[$lineId,$cid]);$tx=one("SELECT * FROM transactions WHERE id=? AND church_id=? AND status='posted' AND bank_line_id IS NULL",[$txId,$cid]);if(!$l||!$tx)throw new RuntimeException('Movimentação não disponível para conciliação.');$dir=(float)$l['amount']>=0?'income':'expense';if($tx['direction']!==$dir||abs((float)$tx['amount']-abs((float)$l['amount']))>.01)throw new RuntimeException('Os valores/tipos não correspondem.');
                q("UPDATE bank_statement_lines SET status='matched',matched_transaction_id=?,resolved_at=NOW() WHERE id=? AND church_id=?",[$txId,$lineId,$cid]);q("UPDATE transactions SET bank_line_id=? WHERE id=? AND church_id=?",[$lineId,$txId,$cid]);audit('manual_reconcile_bank','bank_statement',$lineId,['transaction_id'=>$txId]);set_flash('Movimentação conciliada.');
            }elseif($action==='ignore'){$id=(int)$_POST['line_id'];q("UPDATE bank_statement_lines SET status='ignored',resolved_at=NOW() WHERE id=? AND church_id=? AND status='pending'",[$id,$cid]);audit('ignore_bank_line','bank_statement',$id);set_flash('Linha marcada como ignorada.');}
        }catch(Throwable $e){set_flash($e->getMessage(),'error');}
        redirect('/?r=reconciliation');
    }
    $accounts=finance_accounts($cid);$lines=all("SELECT b.*,a.name account_name FROM bank_statement_lines b LEFT JOIN accounts a ON a.id=b.account_id WHERE b.church_id=? ORDER BY FIELD(b.status,'pending','matched','ignored'),b.transaction_date DESC,b.id DESC LIMIT 250",[$cid]);
    $pending=(int)(one("SELECT COUNT(*) c FROM bank_statement_lines WHERE church_id=? AND status='pending'",[$cid])['c']??0);
    page_top('Conciliação bancária','Compare o extrato com o sistema e descubra o que ficou sem lançar');flash();
    echo '<div class="grid"><div class="card metric"><small>Linhas pendentes</small><strong class="'.($pending?'money out':'money in').'">'.$pending.'</strong></div><div class="card metric"><small>Objetivo</small><strong>0</strong><span class="metric-sub">Nada no banco sem explicação</span></div></div><br>';
    echo '<div class="card"><h3>Importar extrato</h3><form method="post" enctype="multipart/form-data">'.csrf_input().'<input type="hidden" name="action" value="upload"><div class="form-grid"><div><label>Conta bancária</label><select name="account_id"><option value="">Não definida</option>';foreach($accounts as $a)echo '<option value="'.(int)$a['id'].'">'.e($a['name']).'</option>';echo '</select></div><div><label>Arquivo</label><input type="file" name="statement" accept=".ofx,.csv" required><small class="hint">OFX é o formato recomendado. CSV também é aceito.</small></div></div><p><button class="btn">Importar extrato</button></p></form><form method="post" class="action-row">'.csrf_input().'<input type="hidden" name="action" value="auto_match"><button class="btn green">Conciliar automaticamente</button></form></div><br>';
    echo '<div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>DATA</th><th>EXTRATO</th><th>VALOR</th><th>STATUS</th><th>CONCILIAR</th></tr></thead><tbody>';
    foreach($lines as $l){$amt=(float)$l['amount'];echo '<tr><td>'.e(br_date((string)$l['transaction_date'])).'</td><td>'.e($l['description']).'</td><td class="money '.($amt>=0?'in':'out').'">'.e(money_br($amt)).'</td><td><span class="pill">'.e(finance_status_label($l['status'])).'</span></td><td>';if($l['status']==='pending'){$dir=$amt>=0?'income':'expense';$cands=all("SELECT id,transaction_date,description,amount FROM transactions WHERE church_id=? AND status='posted' AND direction=? AND ABS(amount-?)<0.01 AND transaction_date BETWEEN DATE_SUB(?,INTERVAL 7 DAY) AND DATE_ADD(?,INTERVAL 7 DAY) AND bank_line_id IS NULL ORDER BY ABS(DATEDIFF(transaction_date,?)),id LIMIT 8",[$cid,$dir,abs($amt),$l['transaction_date'],$l['transaction_date'],$l['transaction_date']]);if($cands){echo '<form method="post" class="reconcile-inline">'.csrf_input().'<input type="hidden" name="action" value="match"><input type="hidden" name="line_id" value="'.(int)$l['id'].'"><select name="transaction_id">';foreach($cands as $c)echo '<option value="'.(int)$c['id'].'">#'.(int)$c['id'].' · '.e(br_date($c['transaction_date'])).' · '.e(cut_text($c['description'],32)).'</option>';echo '</select><button class="btn">Conciliar</button></form>';}else echo '<a class="btn" href="/?r=finance&bank_line='.(int)$l['id'].'">Criar lançamento</a>';echo '<form method="post" class="inline-mini">'.csrf_input().'<input type="hidden" name="action" value="ignore"><input type="hidden" name="line_id" value="'.(int)$l['id'].'"><button class="btn light">Ignorar</button></form>';}else echo '—';echo '</td></tr>';}
    echo '</tbody></table></div></div>';page_bottom();exit;
}

function finance_route_budgets(int $cid): never {
    finance_pro_guard();finance_seed_defaults($cid);$month=(string)($_GET['month']??date('Y-m'));[$from,$to,$month]=finance_month_bounds($month);
    if($_SERVER['REQUEST_METHOD']==='POST'){
        verify_csrf();$action=(string)($_POST['action']??'budget');
        try{
            if($action==='budget'){$cat=finance_category($cid,(int)$_POST['category_id']);if(!$cat)throw new RuntimeException('Categoria inválida.');q("INSERT INTO finance_budgets(church_id,year,month,direction,category_id,category,fund_id,cost_center_id,planned_amount,notes,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?)",[$cid,(int)substr($month,0,4),(int)substr($month,5,2),$cat['direction']==='both'?'expense':$cat['direction'],(int)$cat['id'],$cat['name'],(int)($_POST['fund_id']??0)?:null,(int)($_POST['cost_center_id']??0)?:null,(float)$_POST['planned_amount'],trim((string)($_POST['notes']??''))?:null,(int)user()['id']]);audit('create_budget','budget',(int)db()->lastInsertId());set_flash('Valor previsto adicionado ao orçamento.');
            }elseif($action==='fund'){$name=trim((string)$_POST['name']);if($name==='')throw new RuntimeException('Informe o nome do fundo.');q('INSERT IGNORE INTO finance_funds(church_id,name,restricted) VALUES(?,?,?)',[$cid,$name,!empty($_POST['restricted'])?1:0]);set_flash('Fundo adicionado.');
            }elseif($action==='cost'){$name=trim((string)$_POST['name']);if($name==='')throw new RuntimeException('Informe o centro de custo.');q('INSERT IGNORE INTO cost_centers(church_id,name) VALUES(?,?)',[$cid,$name]);set_flash('Centro de custo adicionado.');
            }elseif($action==='category'){$name=trim((string)$_POST['name']);$dir=in_array((string)$_POST['direction'],['income','expense','both'],true)?(string)$_POST['direction']:'expense';if($name==='')throw new RuntimeException('Informe a categoria.');q('INSERT IGNORE INTO finance_categories(church_id,name,direction,accounting_code,transparency_group) VALUES(?,?,?,?,?)',[$cid,$name,$dir,trim((string)($_POST['accounting_code']??''))?:null,trim((string)($_POST['transparency_group']??''))?:null]);set_flash('Categoria adicionada.');
            }elseif($action==='delete_budget'){q('DELETE FROM finance_budgets WHERE id=? AND church_id=?',[(int)$_POST['id'],$cid]);set_flash('Item removido do orçamento.');}
        }catch(Throwable $e){set_flash($e->getMessage(),'error');}
        redirect('/?r=budgets&month='.urlencode($month));
    }
    $budgets=all("SELECT b.*,fc.name category_name,f.name fund_name,c.name cost_center_name,(SELECT COALESCE(SUM(t.amount),0) FROM transactions t WHERE t.church_id=b.church_id AND t.status='posted' AND t.direction=b.direction AND t.transaction_date BETWEEN ? AND ? AND (t.category_id=b.category_id OR (t.category_id IS NULL AND t.category=b.category))) actual FROM finance_budgets b LEFT JOIN finance_categories fc ON fc.id=b.category_id LEFT JOIN finance_funds f ON f.id=b.fund_id LEFT JOIN cost_centers c ON c.id=b.cost_center_id WHERE b.church_id=? AND b.year=? AND b.month=? ORDER BY b.direction,b.category",[$from,$to,$cid,(int)substr($month,0,4),(int)substr($month,5,2)]);
    $cats=finance_categories($cid);$funds=finance_funds($cid);$centers=finance_cost_centers($cid);$planned=0;$actual=0;foreach($budgets as $b)if($b['direction']==='expense'){$planned+=(float)$b['planned_amount'];$actual+=(float)$b['actual'];}
    page_top('Planejamento e orçamento','Previsto x realizado · fundos, centros de custo e categorias');flash();
    echo '<div class="toolbar"><form method="get" class="month-picker"><input type="hidden" name="r" value="budgets"><label>Mês</label><input type="month" name="month" value="'.e($month).'" onchange="this.form.submit()"></form></div><div class="grid"><div class="card metric"><small>Despesas previstas</small><strong>'.e(money_br($planned)).'</strong></div><div class="card metric"><small>Despesas realizadas</small><strong class="money out">'.e(money_br($actual)).'</strong></div><div class="card metric"><small>Disponível no orçamento</small><strong>'.e(money_br($planned-$actual)).'</strong></div></div><br>';
    echo '<div class="budget-layout"><div class="card"><h3>Adicionar previsão</h3><form method="post">'.csrf_input().'<input type="hidden" name="action" value="budget"><div class="form-grid"><div><label>Categoria</label><select name="category_id">';foreach($cats as $c)echo '<option value="'.(int)$c['id'].'">'.e($c['name']).' · '.e($c['direction']).'</option>';echo '</select></div><div><label>Valor previsto</label><input type="number" step="0.01" min="0" name="planned_amount" required></div><div><label>Fundo</label><select name="fund_id"><option value="">Não definido</option>';foreach($funds as $f)echo '<option value="'.(int)$f['id'].'">'.e($f['name']).'</option>';echo '</select></div><div><label>Centro de custo</label><select name="cost_center_id"><option value="">Não definido</option>';foreach($centers as $c)echo '<option value="'.(int)$c['id'].'">'.e($c['name']).'</option>';echo '</select></div><div class="full"><label>Observação</label><input name="notes"></div></div><p><button class="btn">Adicionar ao orçamento</button></p></form></div><div class="card"><h3>Estrutura financeira</h3><details><summary>+ Novo fundo / projeto</summary><form method="post">'.csrf_input().'<input type="hidden" name="action" value="fund"><label>Nome</label><input name="name" required><label><input type="checkbox" name="restricted" value="1"> Destinação restrita</label><button class="btn">Adicionar</button></form></details><details><summary>+ Novo centro de custo</summary><form method="post">'.csrf_input().'<input type="hidden" name="action" value="cost"><label>Nome</label><input name="name" required><button class="btn">Adicionar</button></form></details><details><summary>+ Nova categoria / plano de contas</summary><form method="post">'.csrf_input().'<input type="hidden" name="action" value="category"><label>Nome</label><input name="name" required><label>Tipo</label><select name="direction"><option value="expense">Despesa</option><option value="income">Receita</option><option value="both">Ambos</option></select><label>Código contábil</label><input name="accounting_code"><label>Grupo no Portal de Transparência</label><input name="transparency_group"><button class="btn">Adicionar</button></form></details></div></div><br>';
    echo '<div class="card"><h3>Previsto x realizado</h3><div class="table-wrap"><table class="table"><thead><tr><th>CATEGORIA</th><th>TIPO</th><th>PREVISTO</th><th>REALIZADO</th><th>DIFERENÇA</th><th>USO</th></tr></thead><tbody>';foreach($budgets as $b){$pl=(float)$b['planned_amount'];$ac=(float)$b['actual'];$pct=$pl>0?min(999,($ac/$pl)*100):0;echo '<tr><td>'.e($b['category_name']?:$b['category']).'</td><td>'.($b['direction']==='income'?'Receita':'Despesa').'</td><td>'.e(money_br($pl)).'</td><td>'.e(money_br($ac)).'</td><td>'.e(money_br($pl-$ac)).'</td><td><div class="budget-bar"><i style="width:'.min(100,$pct).'%"></i></div><small>'.number_format($pct,1,',','.').'%</small></td></tr>';}if(!$budgets)echo '<tr><td colspan="6">Nenhum orçamento cadastrado neste mês.</td></tr>';echo '</tbody></table></div></div>';page_bottom();exit;
}

function finance_route_closing(int $cid): never {
    finance_pro_guard();$month=(string)($_GET['month']??date('Y-m'));[$from,$to,$month]=finance_month_bounds($month);finance_ensure_occurrences($cid,$month);$p=finance_pending_summary($cid,$month);$tot=finance_period_totals($cid,$from,$to);$closure=one("SELECT * FROM financial_period_closures WHERE church_id=? AND period_month=?",[$cid,$month]);
    if($_SERVER['REQUEST_METHOD']==='POST'){
        verify_csrf();$action=(string)($_POST['action']??'close');
        try{
            if($action==='close'){
                $p=finance_pending_summary($cid,$month);$critical=(int)$p['missing_receipts']+(int)$p['bank_pending']+(int)$p['recurring_pending']+(int)$p['overdue_payables'];if($critical>0)throw new RuntimeException('Resolva as pendências automáticas antes de fechar o mês.');
                foreach(['cash_checked','bank_checked','receipts_checked'] as $k)if(empty($_POST[$k]))throw new RuntimeException('Marque todos os itens de conferência.');
                $tot=finance_period_totals($cid,$from,$to);$check=['cash_checked'=>true,'bank_checked'=>true,'receipts_checked'=>true,'closed_from_ip'=>client_ip_hash(app_key())];
                q("INSERT INTO financial_period_closures(church_id,period_month,opening_balance,income_total,expense_total,closing_balance,checklist_json,status,closed_by,closed_at) VALUES(?,?,?,?,?,?,?,'closed',?,NOW()) ON DUPLICATE KEY UPDATE opening_balance=VALUES(opening_balance),income_total=VALUES(income_total),expense_total=VALUES(expense_total),closing_balance=VALUES(closing_balance),checklist_json=VALUES(checklist_json),status='closed',closed_by=VALUES(closed_by),closed_at=NOW(),reopened_by=NULL,reopened_at=NULL,reopen_reason=NULL",[$cid,$month,$tot['opening'],$tot['income'],$tot['expense'],$tot['closing'],json_encode($check),(int)user()['id']]);audit('close_financial_period','financial_period',null,['month'=>$month]);set_flash('Mês fechado. Novos lançamentos neste período ficam bloqueados até uma reabertura autorizada.');
            }elseif($action==='reopen'){
                if(!can_manage_users())throw new RuntimeException('Somente Pastor/Administrador pode reabrir um período.');$reason=trim((string)($_POST['reason']??''));if(strlen($reason)<8)throw new RuntimeException('Explique o motivo da reabertura.');
                q("UPDATE financial_period_closures SET status='reopened',reopened_by=?,reopened_at=NOW(),reopen_reason=? WHERE church_id=? AND period_month=?",[(int)user()['id'],$reason,$cid,$month]);audit('reopen_financial_period','financial_period',null,['month'=>$month,'reason'=>$reason]);set_flash('Período reaberto. A ação ficou registrada na auditoria.');
            }
        }catch(Throwable $e){set_flash($e->getMessage(),'error');}
        redirect('/?r=closing&month='.urlencode($month));
    }
    $closure=one("SELECT * FROM financial_period_closures WHERE church_id=? AND period_month=?",[$cid,$month]);page_top('Fechamento mensal','Checklist para terminar o mês sem lançamento esquecido');flash();
    echo '<div class="toolbar"><form method="get" class="month-picker"><input type="hidden" name="r" value="closing"><label>Mês</label><input type="month" name="month" value="'.e($month).'" onchange="this.form.submit()"></form></div><div class="grid"><div class="card metric"><small>Saldo inicial</small><strong>'.e(money_br((float)$tot['opening'])).'</strong></div><div class="card metric"><small>Entradas</small><strong class="money in">'.e(money_br((float)$tot['income'])).'</strong></div><div class="card metric"><small>Saídas</small><strong class="money out">'.e(money_br((float)$tot['expense'])).'</strong></div><div class="card metric"><small>Saldo final</small><strong>'.e(money_br((float)$tot['closing'])).'</strong></div></div><br>';
    echo '<div class="closing-layout"><div class="card"><h3>Conferência automática</h3>';foreach([['Comprovantes pendentes',$p['missing_receipts'],'finance'],['Extrato sem conciliar',$p['bank_pending'],'reconciliation'],['Recorrências pendentes',$p['recurring_pending'],'recurring'],['Contas vencidas',$p['overdue_payables'],'payables']] as $i)echo '<a class="check-row '.($i[1]?'check-bad':'check-ok').'" href="/?r='.$i[2].'"><span>'.($i[1]?'!':'✓').'</span><b>'.$i[0].'</b><strong>'.(int)$i[1].'</strong></a>';echo '</div><div class="card"><h3>Status do fechamento</h3>';
    if($closure&&$closure['status']==='closed'){echo '<div class="closed-stamp">MÊS FECHADO<small>'.e((string)$closure['closed_at']).'</small></div>';if(can_manage_users())echo '<form method="post">'.csrf_input().'<input type="hidden" name="action" value="reopen"><label>Motivo para reabrir</label><textarea name="reason" required></textarea><button class="btn danger">Reabrir período</button></form>';}else{echo '<form method="post">'.csrf_input().'<input type="hidden" name="action" value="close"><label class="check-manual"><input type="checkbox" name="cash_checked" value="1"> Conferi o caixa físico e o saldo inicial/final.</label><label class="check-manual"><input type="checkbox" name="bank_checked" value="1"> Conferi os extratos e a conciliação bancária.</label><label class="check-manual"><input type="checkbox" name="receipts_checked" value="1"> Conferi recibos, notas e comprovantes.</label><button class="btn green">Fechar mês</button></form>';}echo '</div></div>';page_bottom();exit;
}

function finance_route_needs(int $cid): never {
