            }elseif($action==='approve'){if(!can_manage_users())throw new RuntimeException('Somente Pastor/Administrador pode aprovar.');$id=(int)$_POST['id'];q("UPDATE church_needs SET status='approved',approved_by=?,approved_at=NOW() WHERE id=? AND church_id=? AND status='requested'",[(int)user()['id'],$id,$cid]);audit('approve_church_need','church_need',$id);set_flash('Necessidade aprovada.');
            }elseif($action==='purchased'){$id=(int)$_POST['id'];q("UPDATE church_needs SET status='purchased',purchased_at=NOW() WHERE id=? AND church_id=? AND status='approved'",[$id,$cid]);audit('purchase_church_need','church_need',$id);set_flash('Necessidade marcada como adquirida.');
            }elseif($action==='cancel'){$id=(int)$_POST['id'];q("UPDATE church_needs SET status='cancelled' WHERE id=? AND church_id=?",[$id,$cid]);audit('cancel_church_need','church_need',$id);set_flash('Necessidade cancelada.');}
