    echo '<div class="need-cards">';foreach($rows as $n){echo '<div class="card need-card priority-'.e($n['priority']).'"><div><span class="pill">'.e(finance_status_label($n['status'])).'</span><h3>'.e($n['title']).'</h3><p>'.e($n['description']??'').'</p><small>'.e($n['cost_center_name']??'Sem área').' · Estimativa '.e(money_br((float)$n['estimated_amount'])).'</small></div><div class="action-row">';if($n['status']==='requested'&&can_manage_users())echo '<form method="post">'.csrf_input().'<input type="hidden" name="action" value="approve"><input type="hidden" name="id" value="'.(int)$n['id'].'"><button class="btn green">Aprovar</button></form>';if($n['status']==='approved')echo '<form method="post">'.csrf_input().'<input type="hidden" name="action" value="purchased"><input type="hidden" name="id" value="'.(int)$n['id'].'"><button class="btn">Marcar comprada</button></form>';echo '</div></div>';}if(!$rows)echo '<div class="dashboard-empty">Nenhuma necessidade registrada.</div>';echo '</div>';page_bottom();exit;
