    echo '<div class="card"><div class="card-title-row"><div><h3>Movimentações detalhadas</h3><p class="muted">A versão em PDF inclui capa, fundos, orçamento, pendências, movimentações e assinaturas.</p></div></div><div class="table-wrap"><table class="table"><thead><tr><th>REF.</th><th>DATA</th><th>TIPO</th><th>CATEGORIA</th><th>HISTÓRICO</th><th>FUNDO</th><th>C. CUSTO</th><th>RECIBO</th><th>VALOR</th></tr></thead><tbody>';foreach(array_reverse(array_slice(array_reverse($d['moves']),0,200)) as $m){$in=$m['direction']==='income';echo '<tr><td>#'.str_pad((string)$m['id'],5,'0',STR_PAD_LEFT).'</td><td>'.e(br_date($m['transaction_date'])).'</td><td>'.($in?'Entrada':'Saída').'</td><td>'.e($m['category']).'</td><td>'.e($m['description']).'</td><td>'.e($m['fund_name']??'—').'</td><td>'.e($m['cost_center_name']??'—').'</td><td>'.($m['receipt_path']?'Sim':'—').'</td><td class="money '.($in?'in':'out').'">'.e(money_br((float)$m['amount'])).'</td></tr>';}echo '</tbody></table></div></div>';page_bottom();exit;
}

function finance_route_transparency(int $cid): never {
    finance_pro_guard();[$period,$from,$to,$label]=period_values((string)($_GET['period']??'month'),(string)($_GET['from']??''),(string)($_GET['to']??''));
    if($_SERVER['REQUEST_METHOD']==='POST'){
        verify_csrf();$action=(string)($_POST['action']??'publish');
        try{
            if($action==='publish'){
                $pf=(string)($_POST['from']??$from);$pt=(string)($_POST['to']??$to);$snap=finance_transparency_snapshot($cid,$pf,$pt);$token=bin2hex(random_bytes(24));$title=trim((string)($_POST['title']??''))?:'Prestação de contas';
                q("INSERT INTO transparency_publications(church_id,token,title,period_from,period_to,snapshot_json,active,published_by,published_at) VALUES(?,?,?,?,?,?,1,?,NOW())",[$cid,$token,$title,$pf,$pt,json_encode($snap,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),(int)user()['id']]);audit('publish_transparency','transparency',(int)db()->lastInsertId(),['from'=>$pf,'to'=>$pt]);set_flash('Prestação de contas publicada. O link pode ser compartilhado com a igreja.');
            }elseif($action==='revoke'){$id=(int)$_POST['id'];q('UPDATE transparency_publications SET active=0,revoked_at=NOW() WHERE id=? AND church_id=?',[$id,$cid]);audit('revoke_transparency','transparency',$id);set_flash('Publicação retirada do ar.');}
        }catch(Throwable $e){set_flash($e->getMessage(),'error');}
        redirect('/?r=transparency');
    }
    $snap=finance_transparency_snapshot($cid,$from,$to);$pubs=all('SELECT * FROM transparency_publications WHERE church_id=? ORDER BY id DESC LIMIT 30',[$cid]);$scheme=(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')?'https':'http';$base=$scheme.'://'.($_SERVER['HTTP_HOST']??'');
    page_top('Portal de Transparência','Publique somente dados consolidados, sem expor nomes de dizimistas ou doadores');flash();
    echo '<div class="transparency-warning"><b>Privacidade protegida</b><p>O portal público não mostra nomes de membros, doadores, dados bancários nem comprovantes. Ele apresenta totais consolidados, categorias, fundos, orçamento e necessidades aprovadas/em acompanhamento.</p></div>';
    echo '<div class="card"><div class="card-title-row"><div><h3>Publicar prestação de contas</h3><p class="muted">A publicação cria um retrato deste período. Alterações futuras no sistema não modificam o relatório já publicado.</p></div></div><form method="post">'.csrf_input().'<input type="hidden" name="action" value="publish"><div class="form-grid"><div><label>Título</label><input name="title" value="Prestação de contas '.e(date('m/Y',strtotime($from))).'"></div><div><label>De</label><input type="date" name="from" value="'.e($from).'"></div><div><label>Até</label><input type="date" name="to" value="'.e($to).'"></div></div><p><button class="btn green">Publicar no Portal de Transparência</button></p></form></div><br>';
    echo '<div class="grid"><div class="card metric"><small>Entradas</small><strong class="money in">'.e(money_br((float)$snap['totals']['income'])).'</strong></div><div class="card metric"><small>Saídas</small><strong class="money out">'.e(money_br((float)$snap['totals']['expense'])).'</strong></div><div class="card metric"><small>Saldo final</small><strong>'.e(money_br((float)$snap['totals']['closing'])).'</strong></div></div><br>';
    echo '<div class="card"><h3>Publicações</h3><div class="table-wrap"><table class="table"><thead><tr><th>TÍTULO</th><th>PERÍODO</th><th>PUBLICADO</th><th>STATUS</th><th>LINK</th></tr></thead><tbody>';foreach($pubs as $p){$url=$base.'/?r=transparency-public&token='.$p['token'];echo '<tr><td>'.e($p['title']).'</td><td>'.e(br_date($p['period_from'])).' a '.e(br_date($p['period_to'])).'</td><td>'.e($p['published_at']).'</td><td><span class="pill">'.($p['active']?'Publicado':'Encerrado').'</span></td><td>';if($p['active'])echo '<a class="btn light" target="_blank" href="'.e($url).'">Abrir portal</a> <input class="share-link" readonly value="'.e($url).'" onclick="this.select()">';else echo '—';echo '</td></tr>';}if(!$pubs)echo '<tr><td colspan="5">Nenhuma prestação de contas publicada.</td></tr>';echo '</tbody></table></div></div>';page_bottom();exit;
}

function finance_route_export(int $cid): never {
    finance_pro_guard();$from=(string)($_GET['from']??date('Y-m-01'));$to=(string)($_GET['to']??date('Y-m-t'));
    $rows=all("SELECT t.id,t.transaction_date,t.direction,fc.accounting_code,t.category,t.description,t.supplier,t.document_number,t.payment_method,t.amount,a.name account_name,f.name fund_name,c.name cost_center_name,t.status FROM transactions t LEFT JOIN finance_categories fc ON fc.id=t.category_id LEFT JOIN accounts a ON a.id=t.account_id LEFT JOIN finance_funds f ON f.id=t.fund_id LEFT JOIN cost_centers c ON c.id=t.cost_center_id WHERE t.church_id=? AND t.transaction_date BETWEEN ? AND ? ORDER BY t.transaction_date,t.id",[$cid,$from,$to]);
    audit('export_accounting_csv','report',null,['from'=>$from,'to'=>$to]);header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="Exportacao-Contador-'.$from.'-'.$to.'.csv"');echo "\xEF\xBB\xBF";$o=fopen('php://output','wb');fputcsv($o,['Referência','Data','Tipo','Código contábil','Categoria','Histórico','Fornecedor','Documento','Forma pagamento','Conta','Fundo','Centro de custo','Valor','Status'],';');foreach($rows as $r)fputcsv($o,['#'.str_pad((string)$r['id'],6,'0',STR_PAD_LEFT),$r['transaction_date'],$r['direction']==='income'?'Receita':'Despesa',$r['accounting_code'],$r['category'],$r['description'],$r['supplier'],$r['document_number'],$r['payment_method'],$r['account_name'],$r['fund_name'],$r['cost_center_name'],number_format((float)$r['amount'],2,',',''),$r['status']],';');fclose($o);exit;
}

function finance_pro_handle(string $route,int $cid): void {
    $routes=['treasury','finance','payables','recurring','reconciliation','budgets','closing','needs','reports','finance-report-pdf','accountant-export','transparency'];
    if(!in_array($route,$routes,true))return;
    finance_seed_defaults($cid);
    if($route==='treasury')finance_route_treasury($cid);
    if($route==='finance')finance_route_finance($cid);
    if($route==='payables')finance_route_payables($cid);
    if($route==='recurring')finance_route_recurring($cid);
    if($route==='reconciliation')finance_route_reconciliation($cid);
    if($route==='budgets')finance_route_budgets($cid);
    if($route==='closing')finance_route_closing($cid);
    if($route==='needs')finance_route_needs($cid);
    if($route==='reports')finance_route_reports($cid);
    if($route==='finance-report-pdf'){finance_pro_guard();$from=(string)($_GET['from']??date('Y-m-01'));$to=(string)($_GET['to']??date('Y-m-t'));finance_pdf_report($cid,$from,$to,(string)($_GET['mode']??'attachment'));}
    if($route==='accountant-export')finance_route_export($cid);
    if($route==='transparency')finance_route_transparency($cid);
}
